sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
   if (isLoading || newValue === '') {
      return;
   }

   var allowedValues = ['N0','DI','MX'];

   if(allowedValues.indexOf(newValue) === -1){
	//g_form.addErrorMessage('Der Wert im Feld Applikation (Stellen 1-2) darf nur: N0, DI oder MX sein, bitte pruefen Sie ihre Eingabe und korrigieren Sie dies!');
	alert('Der Wert im Feld Applikation (Stellen 1-2) darf nur: N0, DI oder MX sein, bitte pruefen Sie ihre Eingabe und korrigieren Sie dies!');
   }

}
